UPDATE ref_occupations SET description='Shoemakers and related workers make, modify and repair standard, custom or orthopaedic footwear and natural or synthetic leather articles, such as luggage, handbags and belts, (except for leather garments, hats and gloves), or participate in the manufacture of shoes and related goods. They decorate, reinforce or finish shoes, luggage, handbags and belts.' WHERE occupation_code='7536' AND level='unit' AND description='Occupational group from the ILO 2025 task dataset (ISCO-08).';
