UPDATE ref_occupations SET description='Fumigators and other pest and weed controllers use chemicals to remove harmful insects, small animals, wild plants and other unwanted organisms, to prevent damage to crops and to buildings and other structures and their surroundings, and to prevent health risks.' WHERE occupation_code='7544' AND level='unit' AND description='Occupational group from the ILO 2025 task dataset (ISCO-08).';
